-- =====================================================================================
-- Réplica del catálogo de turnos: DATOS_ANALISIS (SQL Server) -> Bono (PostgreSQL)
-- Tabla destino: Bono.public.levelup_turnos
-- =====================================================================================
--
-- HALLAZGOS DE LA INSPECCIÓN (ejecutada, no asumida) — ver PARTE 0 para las consultas
-- --------------------------------------------------------------------------------
--   Origen           : [Datos].[dbo].[TURNO]   (BASE TABLE, no vista)
--   Motor origen     : Microsoft SQL Server 2022 (16.0.4255.1)
--   Columnas         : 40, todas NOT NULL
--   Llave primaria   : PK_TURNO (TU_CODIGO, char(6))
--   Otros índices    : ninguno además de la PK
--   Filas            : 76
--   Único otro objeto con "TURNO/HORARIO" en el nombre: dbo.HORARIO (catálogo de
--   horarios, referenciado por TU_HOR_1..7 — NO es el catálogo de turnos).
--   Las ~25 columnas CB_TURNO/PU_TURNO/PL_TURNO en otras tablas son referencias
--   al código de turno, no el catálogo.
--
-- RESTRICCIÓN IMPORTANTE — NO SE PUEDE HACER UN INSERT ... SELECT DIRECTO
-- --------------------------------------------------------------------------------
--   El punto 7 del requerimiento (nombres calificados en la misma instancia) NO es
--   aplicable: origen y destino son MOTORES DISTINTOS en INSTANCIAS DISTINTAS
--     - DATOS_ANALISIS = SQL Server 2022
--     - Bono           = PostgreSQL 17.9
--   Se verificó en Bono: `pg_available_extensions` ofrece postgres_fdw y dblink,
--   pero NO tds_fdw / mssql_fdw, así que Postgres no puede leer SQL Server.
--   Un linked server desde SQL Server hacia Postgres implicaría DDL/config en
--   DATOS_ANALISIS, prohibido por las reglas del proyecto.
--
--   Solución adoptada: la PARTE 2 trae un INSERT ... VALUES con las 76 filas reales
--   extraídas del origen, y la PARTE 2-BIS trae el generador T-SQL que reproduce ese
--   mismo bloque contra cualquier instancia (p. ej. producción) sin escribir nada.
--
-- CÓMO EJECUTAR
-- --------------------------------------------------------------------------------
--   PARTE 0  -> en DATOS_ANALISIS (SQL Server). Solo SELECT, no modifica nada.
--   PARTE 1  -> en Bono (PostgreSQL). Creación de tabla.
--   PARTE 2  -> en Bono (PostgreSQL). Carga de datos.
--   PARTE 3  -> una mitad en cada motor; se comparan los resultados a mano.
--   Las tres partes de Bono van dentro de una sola transacción (BEGIN/COMMIT).
--
-- ESTE SCRIPT YA NO ES EL MANTENIMIENTO VIVO DE LA RÉPLICA
-- --------------------------------------------------------------------------------
--   Desde que Ajustes Comedor calcula la rotación a partir de TU_RIT_PAT/TU_RIT_INI,
--   la réplica dejó de ser un catálogo de nombres y pasó a ser la fuente de a qué hora
--   come la gente. Un turno nuevo o un ritmo editado en TRESS desfasaría las
--   proyecciones sin producir ningún error, así que el refresco lo hace ahora un job:
--
--     docker-compose exec backend python -m app.scripts.sync_turnos_catalogo --execute
--
--   (job diario de las 03:40; también sincroniza dbo.HORARIO → levelup_horarios).
--   Este script se conserva como documentación del DDL, para bootstrap de un entorno
--   nuevo y como referencia forense de los datos que había al crearlo.
--
-- CÓMO SE RELACIONA CON ALEMBIC
-- --------------------------------------------------------------------------------
--   La tabla ya existe como migración del proyecto:
--     - modelo    : app/models/turnos.py  (clase Turno)
--     - migración : alembic/versions/b1t2u3r4n5o6_levelup_turnos_replica_tress.py
--   Si el entorno se migra con Alembic, la PARTE 1 de este script YA está aplicada
--   y hay que saltarla: correr solo la PARTE 2 (carga) y la PARTE 3 (validación).
--   El `CREATE TABLE IF NOT EXISTS` de la PARTE 1 es inofensivo si se ejecuta igual,
--   pero crear la tabla a mano en un entorno sin la migración deja `alembic_version`
--   desincronizada. La PARTE 1 se conserva como documentación del DDL exacto y para
--   entornos donde se replique el catálogo fuera del ciclo de Alembic.
-- =====================================================================================


-- =====================================================================================
-- PARTE 0 — DIAGNÓSTICO / IDENTIFICACIÓN DEL ORIGEN   [SQL Server: DATOS_ANALISIS]
-- Solo lectura. Estas son las consultas que se usaron para localizar dbo.TURNO.
-- =====================================================================================

-- 0.1 Localizar tablas/vistas candidatas por nombre.
--     Resultado real: dbo.HORARIO (BASE TABLE) y dbo.TURNO (BASE TABLE).
SELECT TABLE_SCHEMA, TABLE_NAME, TABLE_TYPE
FROM INFORMATION_SCHEMA.TABLES
WHERE TABLE_NAME LIKE '%TURNO%'
   OR TABLE_NAME LIKE '%SHIFT%'
   OR TABLE_NAME LIKE '%HORARIO%'
   OR TABLE_NAME LIKE '%JORNADA%'
ORDER BY TABLE_TYPE, TABLE_SCHEMA, TABLE_NAME;

-- 0.2 Localizar columnas relacionadas (para descartar tablas que solo referencian
--     el turno en lugar de definirlo).
SELECT TABLE_SCHEMA, TABLE_NAME, COLUMN_NAME
FROM INFORMATION_SCHEMA.COLUMNS
WHERE COLUMN_NAME LIKE '%TURNO%' OR COLUMN_NAME LIKE '%SHIFT%'
ORDER BY TABLE_SCHEMA, TABLE_NAME, COLUMN_NAME;

-- 0.3 Estructura de dbo.TURNO: columnas, tipos, longitudes, nulabilidad.
SELECT ORDINAL_POSITION, COLUMN_NAME, DATA_TYPE,
       CHARACTER_MAXIMUM_LENGTH, NUMERIC_PRECISION, NUMERIC_SCALE,
       IS_NULLABLE, COLUMN_DEFAULT
FROM INFORMATION_SCHEMA.COLUMNS
WHERE TABLE_SCHEMA = 'dbo' AND TABLE_NAME = 'TURNO'
ORDER BY ORDINAL_POSITION;

-- 0.4 Llave primaria y demás restricciones.
SELECT tc.CONSTRAINT_TYPE, tc.CONSTRAINT_NAME, ccu.COLUMN_NAME
FROM INFORMATION_SCHEMA.TABLE_CONSTRAINTS tc
LEFT JOIN INFORMATION_SCHEMA.CONSTRAINT_COLUMN_USAGE ccu
       ON tc.CONSTRAINT_NAME = ccu.CONSTRAINT_NAME
WHERE tc.TABLE_SCHEMA = 'dbo' AND tc.TABLE_NAME = 'TURNO';

-- 0.5 Índices (para saber si hay unicidades adicionales que replicar).
SELECT i.name AS indice, i.is_unique, i.is_primary_key, c.name AS columna, ic.key_ordinal
FROM sys.indexes i
JOIN sys.index_columns ic ON i.object_id = ic.object_id AND i.index_id = ic.index_id
JOIN sys.columns c        ON c.object_id = ic.object_id AND c.column_id = ic.column_id
WHERE i.object_id = OBJECT_ID('dbo.TURNO')
ORDER BY i.name, ic.key_ordinal;

-- 0.6 Volumen.
SELECT COUNT(*) AS total_turnos FROM dbo.TURNO;


-- =====================================================================================
-- PARTE 1 — CREACIÓN DE LA TABLA   [PostgreSQL: Bono]
-- =====================================================================================
--
-- Mapeo de tipos SQL Server -> PostgreSQL (1:1, sin columnas inventadas):
--   char(n)        -> char(n)          varchar(n)  -> varchar(n)
--   smallint       -> smallint         int         -> integer
--   numeric(15,2)  -> numeric(15,2)    numeric(15,5) -> numeric(15,5)
--   datetime       -> timestamp without time zone
--     (el datetime de SQL Server tiene resolución ~3.33 ms; el timestamp de
--      PostgreSQL, de microsegundos, la contiene sin pérdida. No se fija
--      precisión para que este DDL coincida con la migración de Alembic.)
--
-- Se replican las 40 columnas del origen, en el mismo orden, todas NOT NULL,
-- y la PK sobre tu_codigo. No se agrega ninguna columna. Los nombres van en
-- minúsculas por convención de PostgreSQL (identificadores sin comillas se
-- pliegan a minúsculas, así que TU_CODIGO y tu_codigo son la misma columna).
--
-- Sobre char(6): tanto SQL Server como PostgreSQL tratan los espacios finales de
-- `char(n)` como no significativos, así que '01    ' del origen se compara igual
-- que '01'. Es el equivalente fiel; el código de la app ya usa RTRIM/normalización.

BEGIN;

-- OPERACIÓN DESTRUCTIVA — deliberadamente comentada. Descomentar solo con
-- confirmación explícita, porque descarta cualquier dato existente en la tabla.
-- DROP TABLE IF EXISTS public.levelup_turnos;

CREATE TABLE IF NOT EXISTS public.levelup_turnos (
    tu_codigo   char(6)         NOT NULL,
    tu_descrip  varchar(100)    NOT NULL,
    tu_dias     smallint        NOT NULL,
    tu_dobles   numeric(15,2)   NOT NULL,
    tu_domingo  numeric(15,2)   NOT NULL,
    tu_festivo  char(1)         NOT NULL,
    tu_hor_1    char(6)         NOT NULL,
    tu_hor_2    char(6)         NOT NULL,
    tu_hor_3    char(6)         NOT NULL,
    tu_hor_4    char(6)         NOT NULL,
    tu_hor_5    char(6)         NOT NULL,
    tu_hor_6    char(6)         NOT NULL,
    tu_hor_7    char(6)         NOT NULL,
    tu_horario  smallint        NOT NULL,
    tu_jornada  numeric(15,2)   NOT NULL,
    tu_nomina   smallint        NOT NULL,
    tu_rit_ini  timestamp       NOT NULL,
    tu_rit_pat  varchar(4096)   NOT NULL,
    tu_tip_1    smallint        NOT NULL,
    tu_tip_2    smallint        NOT NULL,
    tu_tip_3    smallint        NOT NULL,
    tu_tip_4    smallint        NOT NULL,
    tu_tip_5    smallint        NOT NULL,
    tu_tip_6    smallint        NOT NULL,
    tu_tip_7    smallint        NOT NULL,
    tu_tip_jor  smallint        NOT NULL,
    tu_ingles   varchar(100)    NOT NULL,
    tu_texto    varchar(100)    NOT NULL,
    tu_numero   numeric(15,2)   NOT NULL,
    tu_hor_fes  char(6)         NOT NULL,
    tu_vaca_ha  numeric(15,2)   NOT NULL,
    tu_vaca_sa  numeric(15,2)   NOT NULL,
    tu_vaca_de  numeric(15,2)   NOT NULL,
    tu_sub_cta  varchar(100)    NOT NULL,
    tu_dias_ba  numeric(15,5)   NOT NULL,
    tu_activo   char(1)         NOT NULL,
    tu_tip_jt   smallint        NOT NULL,
    llave       integer         NOT NULL,
    tu_nivel0   varchar(255)    NOT NULL,
    tu_sat_jor  char(6)         NOT NULL,
    CONSTRAINT pk_levelup_turnos PRIMARY KEY (tu_codigo)
);

COMMENT ON TABLE public.levelup_turnos IS
    'Réplica de solo lectura del catálogo [Datos].[dbo].[TURNO] de DATOS_ANALISIS (TRESS). No es fuente de verdad: se recarga desde el origen.';


-- =====================================================================================
-- PARTE 2 — CARGA DE DATOS   [PostgreSQL: Bono]
-- 76 filas extraídas de [Datos].[dbo].[TURNO] con el SELECT de la PARTE 2-BIS.
--
-- Columnas explícitas en el INSERT (sin SELECT *). Idempotente: ON CONFLICT
-- actualiza la fila existente en lugar de fallar, de modo que el script se puede
-- volver a correr para refrescar la réplica sin TRUNCATE ni DELETE.
--
-- Los literales E'...' de tu_rit_pat conservan los CRLF del origen: 23 de los 76
-- patrones rotativos terminan en CR+LF y se replican byte a byte.
-- =====================================================================================

