-- =====================================================================================
-- PARTE 2-BIS — GENERADOR DEL BLOQUE VALUES   [SQL Server: DATOS_ANALISIS]
-- Solo lectura. Sirve para regenerar la PARTE 2 contra otra instancia (producción)
-- sin escribir nada en el origen. Copiar la salida y pegarla en el INSERT de arriba.
-- =====================================================================================

-- 2-BIS.a  GUARDA: el generador asume que ninguna columna de texto trae comillas
--          simples ni backslashes (verificado en la instancia inspeccionada: 0 filas).
--          Si esta consulta devuelve algo distinto de 0, NO usar el generador tal cual:
--          hay que escapar esos caracteres antes de pegar la salida.
SELECT SUM(CASE WHEN CHARINDEX('''', TU_CODIGO + TU_DESCRIP + TU_FESTIVO
                + TU_HOR_1 + TU_HOR_2 + TU_HOR_3 + TU_HOR_4 + TU_HOR_5 + TU_HOR_6
                + TU_HOR_7 + TU_RIT_PAT + TU_INGLES + TU_TEXTO + TU_HOR_FES
                + TU_SUB_CTA + TU_ACTIVO + TU_NIVEL0 + TU_SAT_JOR) > 0
                THEN 1 ELSE 0 END) AS filas_con_comilla,
       SUM(CASE WHEN CHARINDEX('\', TU_CODIGO + TU_DESCRIP + TU_FESTIVO
                + TU_HOR_1 + TU_HOR_2 + TU_HOR_3 + TU_HOR_4 + TU_HOR_5 + TU_HOR_6
                + TU_HOR_7 + TU_RIT_PAT + TU_INGLES + TU_TEXTO + TU_HOR_FES
                + TU_SUB_CTA + TU_ACTIVO + TU_NIVEL0 + TU_SAT_JOR) > 0
                THEN 1 ELSE 0 END) AS filas_con_backslash
FROM dbo.TURNO;

-- 2-BIS.b  Generador. Emite una línea "(...)," por turno; a la última hay que
--          quitarle la coma final antes de pegarla.
--          Sólo TU_RIT_PAT se emite como E'...' porque es la única columna con
--          caracteres de control (CR/LF); el resto va como literal simple.
SELECT '    ('
    + ''''  + t.TU_CODIGO  + ''', '
    + ''''  + t.TU_DESCRIP + ''', '
    + CAST(t.TU_DIAS    AS varchar(20)) + ', '
    + CAST(t.TU_DOBLES  AS varchar(40)) + ', '
    + CAST(t.TU_DOMINGO AS varchar(40)) + ', '
    + ''''  + t.TU_FESTIVO + ''', '
    + ''''  + t.TU_HOR_1 + ''', ' + '''' + t.TU_HOR_2 + ''', '
    + ''''  + t.TU_HOR_3 + ''', ' + '''' + t.TU_HOR_4 + ''', '
    + ''''  + t.TU_HOR_5 + ''', ' + '''' + t.TU_HOR_6 + ''', '
    + ''''  + t.TU_HOR_7 + ''', '
    + CAST(t.TU_HORARIO AS varchar(20)) + ', '
    + CAST(t.TU_JORNADA AS varchar(40)) + ', '
    + CAST(t.TU_NOMINA  AS varchar(20)) + ', '
    + '''' + CONVERT(varchar(23), t.TU_RIT_INI, 121) + ''', '
    + 'E''' + REPLACE(REPLACE(REPLACE(t.TU_RIT_PAT, CHAR(13), '\r'),
                              CHAR(10), '\n'), CHAR(9), '\t') + ''', '
    + CAST(t.TU_TIP_1 AS varchar(20)) + ', ' + CAST(t.TU_TIP_2 AS varchar(20)) + ', '
    + CAST(t.TU_TIP_3 AS varchar(20)) + ', ' + CAST(t.TU_TIP_4 AS varchar(20)) + ', '
    + CAST(t.TU_TIP_5 AS varchar(20)) + ', ' + CAST(t.TU_TIP_6 AS varchar(20)) + ', '
    + CAST(t.TU_TIP_7 AS varchar(20)) + ', '
    + CAST(t.TU_TIP_JOR AS varchar(20)) + ', '
    + '''' + t.TU_INGLES + ''', '
    + '''' + t.TU_TEXTO  + ''', '
    + CAST(t.TU_NUMERO AS varchar(40)) + ', '
    + '''' + t.TU_HOR_FES + ''', '
    + CAST(t.TU_VACA_HA AS varchar(40)) + ', '
    + CAST(t.TU_VACA_SA AS varchar(40)) + ', '
    + CAST(t.TU_VACA_DE AS varchar(40)) + ', '
    + '''' + t.TU_SUB_CTA + ''', '
    + CAST(t.TU_DIAS_BA AS varchar(40)) + ', '
    + '''' + t.TU_ACTIVO + ''', '
    + CAST(t.TU_TIP_JT AS varchar(20)) + ', '
    + CAST(t.LLAVE      AS varchar(20)) + ', '
    + '''' + t.TU_NIVEL0  + ''', '
    + '''' + t.TU_SAT_JOR + ''''
    + '),' AS linea_values
FROM dbo.TURNO t
ORDER BY t.TU_CODIGO;


-- =====================================================================================
-- PARTE 3 — VALIDACIÓN
-- Cross-engine: se ejecuta una consulta en cada motor y se comparan los resultados.
-- =====================================================================================

-- 3.a  ORIGEN  [SQL Server: DATOS_ANALISIS]
--      Valores obtenidos en la instancia inspeccionada:
--        total = 76 | suma_llave = 6772 | suma_jornada = 3529.50 | suma_long_descrip = 1474
SELECT COUNT(*)                                   AS total,
       SUM(CAST(LLAVE AS bigint))                 AS suma_llave,
       SUM(CAST(TU_JORNADA AS numeric(20,2)))     AS suma_jornada,
       SUM(LEN(RTRIM(TU_DESCRIP)))                AS suma_long_descrip
FROM dbo.TURNO;

-- 3.b  DESTINO  [PostgreSQL: Bono]
--      Debe arrojar exactamente los mismos cuatro valores que 3.a.
SELECT COUNT(*)                    AS total,
       SUM(llave::bigint)          AS suma_llave,
       SUM(tu_jornada)::numeric(20,2) AS suma_jornada,
       SUM(length(rtrim(tu_descrip))) AS suma_long_descrip
FROM public.levelup_turnos;

-- 3.c  DESTINO  [PostgreSQL: Bono] — control de integridad de la réplica.
--      Esperado: 0 duplicados, 0 códigos vacíos, y 23 patrones rotativos con CRLF
--      (mismo número que reporta 3.d en el origen).
SELECT (SELECT COUNT(*) FROM (SELECT tu_codigo FROM public.levelup_turnos
          GROUP BY tu_codigo HAVING COUNT(*) > 1) d)          AS codigos_duplicados,
       (SELECT COUNT(*) FROM public.levelup_turnos
          WHERE btrim(tu_codigo) = '')                        AS codigos_vacios,
       (SELECT COUNT(*) FROM public.levelup_turnos
          WHERE tu_rit_pat LIKE '%' || chr(13) || '%')        AS patrones_con_cr;

-- 3.d  ORIGEN  [SQL Server: DATOS_ANALISIS] — contraparte de 3.c.
SELECT COUNT(*) AS patrones_con_cr
FROM dbo.TURNO
WHERE TU_RIT_PAT LIKE '%' + CHAR(13) + '%';

-- 3.e  DESTINO  [PostgreSQL: Bono] — vistazo a los turnos cargados.
SELECT rtrim(tu_codigo) AS codigo, tu_descrip, tu_dias, tu_jornada,
       tu_activo, rtrim(tu_hor_1) AS horario_lunes,
       CASE WHEN btrim(tu_rit_pat) = '' THEN 'fijo' ELSE 'rotativo' END AS tipo
FROM public.levelup_turnos
ORDER BY tu_codigo;
